    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

interface TodoRepository {
    Todo simpan(String judul);

    List<Todo> semua();

    Todo cari(int id);

    boolean hapus(int id);

    void perbarui(Todo todo);
}

class TodoTidakDitemukanException extends RuntimeException {
    TodoTidakDitemukanException(int id) {
        super("Todo nomor " + id + " tidak ditemukan");
    }
}

class TodoService {
    private final TodoRepository repo;

    TodoService(TodoRepository repo) {
        this.repo = repo;
    }

    Todo tambah(String judul) {
        if (judul == null || judul.trim().isEmpty()) {
            throw new IllegalArgumentException("Judul tidak boleh kosong");
        }
        if (judul.trim().length() > 50) {
            throw new IllegalArgumentException("Judul maksimal 50 huruf");
        }
        return repo.simpan(judul.trim());
    }

    void selesaikan(int id) {
        Todo t = repo.cari(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        t.selesaikan();
        repo.perbarui(t);
    }

    void hapus(int id) {
        if (!repo.hapus(id)) {
            throw new TodoTidakDitemukanException(id);
        }
    }

    List<Todo> semua() {
        return repo.semua();
    }
}

class TodoRepositoryJdbc implements TodoRepository {
    private final DataSource ds;

    TodoRepositoryJdbc(DataSource ds) {
        this.ds = ds;
    }

    public Todo simpan(String judul) {
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("INSERT INTO todo (judul) VALUES (?)", Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, judul);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                rs.next();
                return new Todo(rs.getInt(1), judul, false);
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal menyimpan todo", e);
        }
    }

    public List<Todo> semua() {
        List<Todo> hasil = new ArrayList<>();
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("SELECT id, judul, selesai FROM todo ORDER BY id");
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                hasil.add(baca(rs));
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal membaca todo", e);
        }
        return hasil;
    }

    public Todo cari(int id) {
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("SELECT id, judul, selesai FROM todo WHERE id = ?")) {
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? baca(rs) : null;
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal mencari todo", e);
        }
    }

    public boolean hapus(int id) {
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("DELETE FROM todo WHERE id = ?")) {
            ps.setInt(1, id);
            return ps.executeUpdate() == 1;
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal menghapus todo", e);
        }
    }

    public void perbarui(Todo todo) {
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("UPDATE todo SET selesai = ? WHERE id = ?")) {
            ps.setBoolean(1, todo.isSelesai());
            ps.setInt(2, todo.getId());
            ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal memperbarui todo", e);
        }
    }

    boolean gantiJudul(int id, String judulBaru) {
        try (Connection c = ds.getConnection();
             PreparedStatement ps = c.prepareStatement("UPDATE todo SET judul = ? WHERE id = ?")) {
            ps.setString(1, judulBaru);
            ps.setInt(2, id);
            return ps.executeUpdate() == 1;
        } catch (SQLException e) {
            throw new IllegalStateException("Gagal mengganti judul", e);
        }
    }

    private Todo baca(ResultSet rs) throws SQLException {
        return new Todo(rs.getInt("id"), rs.getString("judul"), rs.getBoolean("selesai"));
    }
}

class TodoView {
    private final TodoService service;
    private final TodoRepositoryJdbc repo;

    TodoView(TodoService service, TodoRepositoryJdbc repo) {
        this.service = service;
        this.repo = repo;
    }

    void jalankan(Scanner in) {
        while (in.hasNextLine()) {
            String baris = in.nextLine().trim();
            if (baris.equals("keluar")) {
                System.out.println("Sampai jumpa!");
                return;
            }
            try {
                proses(baris);
            } catch (IllegalArgumentException | TodoTidakDitemukanException e) {
                System.out.println("Gagal: " + e.getMessage());
            }
        }
    }

    void proses(String baris) {
        String[] p = baris.split(" ", 2);
        String isi = p.length > 1 ? p[1] : "";
        switch (p[0]) {
            case "tambah":
                Todo t = service.tambah(isi);
                System.out.println("Ditambah: " + t);
                break;
            case "selesai":
                service.selesaikan(angka(isi));
                System.out.println("Selesai nomor " + isi);
                break;
            case "ubah":
                String[] u = isi.split(" ", 2);
                if (u.length < 2) {
                    throw new IllegalArgumentException("Format: ubah <nomor> <judul baru>");
                }
                repo.gantiJudul(angka(u[0]), u[1]);
                System.out.println("Diubah: " + repo.cari(angka(u[0])));
                break;
            case "hapus":
                service.hapus(angka(isi));
                System.out.println("Dihapus nomor " + isi);
                break;
            case "lihat":
                lihat();
                break;
            default:
                System.out.println("Perintah tidak dikenal: " + p[0]);
        }
    }

    void lihat() {
        List<Todo> semua = service.semua();
        if (semua.isEmpty()) {
            System.out.println("Belum ada todo");
        }
        for (Todo t : semua) {
            System.out.println(t);
        }
    }

    private int angka(String s) {
        try {
            return Integer.parseInt(s.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Nomor harus angka: " + s);
        }
    }
}
